import{_ as o,I as r,g as a,j as e}from"./chunks/framework.CjoWWfVe.js";const g=JSON.parse('{"title":"О философии проекта","description":"Философия бережливого и комфортного учета ОмниКрафт ЕРП для ремесленников с бизнес-мышлением.","frontmatter":{"title":"О философии проекта","description":"Философия бережливого и комфортного учета ОмниКрафт ЕРП для ремесленников с бизнес-мышлением.","order":1},"headers":[],"relativePath":"ru/docs/introduction.md","filePath":"ru/docs/introduction.md"}'),n={name:"ru/docs/introduction.md"};function s(i,t,l,p,c,d){return r(),a("div",null,[...t[0]||(t[0]=[e('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="о-философии-проекта" tabindex="-1">О философии проекта <a class="header-anchor" href="#о-философии-проекта" aria-label="Permalink to &quot;О философии проекта&quot;">​</a></h1><p>Добро пожаловать в <strong>ОмниКрафт ЕРП</strong> — программу управленческого учета, созданную изначально кожевниками для кожевников, но отлично подходящую для любых ремесленных микропроизводств.</p><p>Большинство традиционных бухгалтерских систем созданы для профессиональных бухгалтеров. Они требуют ручного ввода первичных документов, постоянного сведения счетов и отвлекают от реальной работы в мастерской.</p><p>ОмниКрафт ЕРП разработана для людей с <strong>бизнес-мышлением</strong>. В основе логики программы лежат практичность и прагматизм: мы стремимся сделать учет комфортным и освободить время мастера для работы.</p><hr><h2 id="🎯-три-фундаментальных-принципа-омникрафт-ерп" tabindex="-1">🎯 Три фундаментальных принципа ОмниКрафт ЕРП <a class="header-anchor" href="#🎯-три-фундаментальных-принципа-омникрафт-ерп" aria-label="Permalink to &quot;🎯 Три фундаментальных принципа ОмниКрафт ЕРП&quot;">​</a></h2><h3 id="_1-🤖-автоматизация-вместо-бухгалтерии" tabindex="-1">1. 🤖 Автоматизация вместо бухгалтерии <a class="header-anchor" href="#_1-🤖-автоматизация-вместо-бухгалтерии" aria-label="Permalink to &quot;1. 🤖 Автоматизация вместо бухгалтерии&quot;">​</a></h3><p>Вам больше не нужно вручную подбивать кассу или строить балансовые отчеты. Система делает это сама, основываясь на ваших естественных действиях в программе: закупках, производстве и продажах.</p><p>Программа автоматически рассчитывает баланс, распределяет затраты на логистику и фиксирует движение денег. Вам не придется вручную сводить цифры — система автоматически готовит ключевые показатели, на которые можно реально опираться. На основе собираемых данных программа выстраивает расчеты и выводит аналитические бизнес-метрики. В дальнейшем этот фундамент позволит расширять состав показателей (например, оценивать отдачу от капитала, рентабельность времени или доходность каналов продаж), давая объективную картину развития мастерской без сложного финансового анализа.</p><h3 id="_2-💸-смешанные-финансы-как-стандарт" tabindex="-1">2. 💸 Смешанные финансы как стандарт <a class="header-anchor" href="#_2-💸-смешанные-финансы-как-стандарт" aria-label="Permalink to &quot;2. 💸 Смешанные финансы как стандарт&quot;">​</a></h3><p>Традиционные учетные системы требуют строгого разделения личных и бизнес-денег. В реальности индивидуального ремесла это правило часто создает только лишнюю рутину: мастер покупает материалы с личной карты, а выручку с продажи тратит на бытовые нужды.</p><p>В ОмниКрафт ЕРП по умолчанию заложен принцип <strong>смешанных финансов</strong>. Программа не принуждает вас искусственно разделять личный карман и кассу мастерской.</p><p><strong>В чем удобство смешанного учета:</strong></p><ul><li><strong>Отсутствие лишних транзакций:</strong> Вы фиксируете только прямые доходы и расходы бизнеса (покупку сырья, оборудования, продажу изделий). Вам не нужно записывать переводы себе «на жизнь» или оплату продуктов с выручки.</li><li><strong>Сохранение точности учета:</strong> Программа все равно с абсолютной точностью рассчитывает себестоимость изделий, маржинальность, окупаемость вашего времени и общую капитализацию мастерской.</li><li><strong>Понимание личных инвестиций:</strong> Отрицательное сальдо ДДС (Движения денежных средств) в этой модели не является ошибкой. Это точный показатель того, какую сумму вы временно «одолжили» бизнесу из личных средств. Когда баланс ДДС переходит в плюс — это означает, что бизнес полностью вернул вам вложенное и начал генерировать чистую денежную прибыль.</li></ul><div class="info custom-block"><p class="custom-block-title">Переход к раздельному учету</p><p>Если ваша мастерская вырастет и вам потребуется вести классический раздельный учет (когда баланс в программе должен с абсолютной точностью совпадать с реальной банковской картой), вы сможете сделать это в любой момент.</p><p>Для этого достаточно завести отдельную карту для бизнеса и добавить в справочник операций ДДС две категории: <em>«Пополнение бизнеса (инвестиции)»</em> и <em>«Списание на личное (вывод прибыли)»</em>.</p></div><h3 id="_3-📈-динамическии-баланс-и-контроль-прибыли" tabindex="-1">3. 📈 Динамический баланс и контроль прибыли <a class="header-anchor" href="#_3-📈-динамическии-баланс-и-контроль-прибыли" aria-label="Permalink to &quot;3. 📈 Динамический баланс и контроль прибыли&quot;">​</a></h3><p>Если вы купили швейную машинку, печь для обжига, компьютер для работы или дорогой профессиональный инструмент, денег на вашей личной карте стало меньше. Но ваш бизнес не обеднел — ценность просто перешла из денежной формы в форму оборудования.</p><p>ОмниКрафт ЕРП автоматически собирает баланс вашей мастерской в реальном времени. Собственный капитал (Чистые активы) вашей мастерской формируется из её физических материальных активов за вычетом внешних долгов бизнеса: <em>Стоимость оборудования (с учетом износа) + Оценка сырья на складе + Стоимость готовых товаров на полке − Долги бизнеса (если они есть).</em></p><blockquote><p><strong>Появление «Свободных денег» на балансе</strong> Свободные деньги как отдельный актив появятся в вашем балансе только в том случае, если вы решите перейти на раздельный учет. Как только вы заведете отдельную бизнес-карту, её остаток станет полноценным активом бизнеса («Свободными деньгами») и начнет прибавляться к стоимости физических активов в балансе.</p></blockquote><p><strong>Как читать ДДС, Прибыль и Баланс вместе?</strong> В грамотном управленческом учете эти показатели не заменяют друг друга, они описывают ваш бизнес с трех разных сторон:</p><ul><li><strong>Сальдо ДДС (Движение денег)</strong> показывает <em>историю денежных потоков</em> (всех, в том числе кредитов и займов). Оно отвечает на вопрос: сколько живых денег мастерская вытянула из вашего личного кармана на закупки или сколько уже успела вернуть обратно.</li><li><strong>Чистая прибыль</strong> показывает <em>конечный финансовый результат работы</em>. Она отвечает на вопрос: эффективно ли вы работаете? Это разница между всеми доходами мастерской (как от реализации, так и внереализационными) и реальными расходами (включая скрытые издержки, такие как износ станков, потребленные на изделие материалы, реклама и налоги).</li><li><strong>Собственный капитал (Баланс)</strong> показывает <em>капитализацию</em>. Он отвечает на вопрос: сколько ваш бизнес стоит прямо сейчас? Это общая ценность всего вашего физического имущества (оборудования, сырья и готовых товаров) и свободных денег (если учёт личных и бизнес-денег ведётся раздельно) за вычетом внешних долгов.</li></ul><p><strong>Отслеживание в динамике:</strong> Чтобы вы могли наглядно оценивать скорость развития своего дела, программа автоматически делает снепшоты (снимки) баланса и ключевых показателей. Это позволяет отслеживать динамику бизнеса: видеть в реальном времени ежедневные колебания внутри текущего месяца, а также анализировать долгосрочные тренды по неделям, месяцам и годам.</p>',23)])])}const m=o(n,[["render",s]]);export{g as __pageData,m as default};
